"""Twelve original protozoal questions in the parasitic-infections chapter."""
from qbank_authoring import question,ref,finalize
AM=ref('CDC DPDx: Amebiasis','https://www.cdc.gov/dpdx/amebiasis/')
AT=ref('Arizona Department of Health: Amebiasis Disease Protocol','https://www.azdhs.gov/documents/preparedness/epidemiology-disease-control/investigation-manual/disease-protocols/amebiasis.pdf')
GI=ref('CDC: Patient Care for Giardia Infection','https://www.cdc.gov/giardia/hcp/clinical-care/index.html')
VL=ref('ASTMH/IDSA: Diagnosis and Treatment of Leishmaniasis','https://www.idsociety.org/practice-guideline/leishmaniasis/')
VI=ref('WHO India: Leishmaniasis','https://www.who.int/india/health-topics/leishmaniasis')
VH=ref('NIH: Leishmaniasis in HIV—Region-Specific Combination Treatment','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/leishmaniasis')
BA=ref('IDSA: Diagnosis and Management of Babesiosis','https://www.idsociety.org/practice-guideline/babesiosis/')
CH=ref('CDC: Clinical Testing and Diagnosis of Chagas Disease','https://www.cdc.gov/chagas/hcp/diagnosis-testing/index.html')
CT=ref('CDC: Clinical Care of Chagas Disease','https://www.cdc.gov/chagas/hcp/clinical-care/index.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Stool microscopy reports an E. histolytica/dispar complex in a patient with diarrhea. What additional diagnostic principle is important?', 'Use appropriate antigen or molecular testing to distinguish pathogenic E. histolytica where available',[
 ('Microscopy always distinguishes these species reliably','They can be morphologically indistinguishable.'),('Every E. dispar detection requires an invasive-amebiasis regimen','It is generally not associated with the same invasive disease.'),('A positive report excludes every bacterial cause of diarrhea','Coexisting or alternative causes remain possible.')],
 'A morphological label can group organisms with different clinical significance', '**Species-specific testing improves attribution.**',['Specimen fixation and timing can affect available methods.','Clinical invasive disease needs prompt treatment when strongly suspected.'], '**Match the result to the actual syndrome.**',['Dysentery and hepatic disease warrant different site assessment.','Avoid treating every nonpathogenic detection as the cause of symptoms.'],[['Microscopy','May report a complex'],['Antigen/PCR','Can distinguish species'],['Clinical decision','Requires syndrome attribution']],[AM])
q('A patient has invasive E. histolytica colitis. Which treatment strategy is appropriate?', 'A tissue-active nitroimidazole followed by a luminal agent such as paromomycin',[
 ('Metronidazole alone without addressing the luminal reservoir','It may not eradicate luminal carriage.'),('Paromomycin alone for severe invasive disease','A luminal drug does not adequately treat tissue invasion.'),('An antibacterial cephalosporin alone','It is not the appropriate antiamebic regimen.')],
 'Tissue invasion and luminal persistence need different drug actions', '**Metronidazole or tinidazole treats invasive tissue disease.**',['A subsequent luminal agent clears remaining intestinal organisms.','Severe colitis requires fluid, complication and surgical-risk assessment.'], '**Complete both components when indicated.**',['Review diagnosis if response is atypical.','Do not confuse symptom improvement with luminal eradication.'],[['Tissue phase','Nitroimidazole'],['Luminal phase','Paromomycin or suitable alternative'],['Goal','Treat invasion and clear carriage']],[AT])
q('An asymptomatic patient has confirmed intestinal E. histolytica infection without evidence of tissue invasion. Which regimen principle is appropriate?', 'A luminal amebicide rather than automatically adding a tissue-invasive-disease regimen',[
 ('No treatment because every asymptomatic species is E. dispar','Confirmed E. histolytica is different from nonpathogenic look-alikes.'),('Metronidazole alone as the ideal luminal-clearance treatment','A luminal agent is needed for carriage eradication.'),('A full antibacterial sepsis regimen','There is no such systemic syndrome in the stem.')],
 'Confirmed infection and its anatomical extent determine treatment', '**Asymptomatic E. histolytica carriage can transmit infection.**',['Species confirmation avoids treating nonpathogenic look-alikes.','A luminal drug addresses intestinal carriage.'], '**Review for overlooked invasive symptoms before selecting the regimen.**',['Ask about dysentery, fever and hepatic symptoms.','Use food, water and hand-hygiene prevention advice.'],[['Asymptomatic confirmed histolytica','Luminal treatment'],['Invasive disease','Tissue plus luminal regimen'],['Dispar','Different significance']],[AT,AM])
q('A patient has persistent greasy diarrhea, bloating and weight loss after untreated-water exposure. Which parasite is characteristic?', 'Giardia duodenalis',[
 ('E. histolytica as the characteristic cause of nonbloody malabsorptive greasy stool','Amebiasis more often raises an invasive/dysenteric differential.'),('Schistosoma haematobium','It classically involves urinary disease.'),('Toxoplasma gondii','It does not typically produce this intestinal malabsorption syndrome.')],
 'A small-bowel protozoal infection can produce malabsorption', '**Giardia causes nonbloody diarrhea and bloating.**',['Antigen or appropriate molecular/stool testing supports diagnosis.','Intermittent shedding can require multiple samples.'], '**Treat symptomatic infection and correct dehydration.**',['Tinidazole, metronidazole or other effective options may be used.','Investigate persistent symptoms rather than assuming every episode is ongoing infection.'],[['Site','Small intestine'],['Pattern','Greasy stool and bloating'],['Evidence','Appropriate stool tests']],[GI],style='clinical_scenario')
q('Symptoms persist after giardiasis treatment. What should be assessed before simply changing drugs?', 'Whether infection persists, whether reinfection or inadequate exposure occurred, and whether postinfectious symptoms explain the course',[
 ('Every symptom proves drug-resistant Giardia','Postinfectious symptoms can outlast clearance.'),('A single symptom-free hour proves permanent cure','Clinical course needs a more structured assessment.'),('Repeated treatment is always preferable to further evaluation','This can create unnecessary adverse effects and miss another cause.')],
 'Microbiological persistence and symptom persistence are different outcomes', '**Reinfection and adherence/absorption problems are common explanations to assess.**',['Repeat appropriate stool testing is useful when symptoms continue.','Postinfectious lactose intolerance or other syndromes can contribute.'], '**Use the result to choose the next step.**',['Persistent proven infection may need a different or combination strategy.','Repeated failures can warrant immune-deficiency evaluation.'],[['Infection status','Confirm with appropriate stool tests'],['Exposure','Reinfection or inadequate course'],['No infection','Consider postinfectious/other causes']],[GI])
q('A patient from an endemic region has prolonged fever, massive splenomegaly and pancytopenia. Which diagnosis is especially important?', 'Visceral leishmaniasis',[
 ('Uncomplicated giardiasis','It does not explain the reticuloendothelial and cytopenic syndrome.'),('Localized cutaneous sporotrichosis','It does not explain this systemic pattern.'),('Asymptomatic intestinal E. dispar','It is not the cause of this illness.')],
 'Reticuloendothelial disease links fever, splenic enlargement and cytopenias', '**Leishmania amastigotes can involve marrow and other tissues.**',['Histoplasmosis, malaria and hematological disease are important alternatives.','HIV can alter presentation and test performance.'], '**Use an appropriate endemic-region diagnostic pathway.**',['Serology and direct parasite/molecular evidence have different roles.','Invasive sampling must account for bleeding risk and local expertise.'],[['Syndrome','Fever, splenomegaly and cytopenias'],['Risk','Endemic exposure'],['Diagnosis','Clinical plus appropriate parasite evidence']],[VL],style='clinical_scenario')
q('A treated kala-azar patient remains rK39 antibody positive after clinical recovery. What is the best interpretation?', 'Antibodies can persist, so rK39 positivity alone is not proof of relapse or a reliable test of cure',[
 ('Persistent antibody always means treatment failure','Serological persistence is recognized.'),('The result identifies antileishmanial susceptibility','It does not.'),('rK39 becomes uninterpretable only if the spleen is normal','The limitation is related to antibody persistence and clinical context.')],
 'A marker of exposure can remain after active disease resolves', '**Interpret rK39 with symptoms and prior treatment.**',['Asymptomatic infection can also produce positivity.','HIV can reduce serological sensitivity.'], '**Investigate suspected relapse with suitable direct or molecular evidence.**',['Do not prescribe retreatment solely from a persistent antibody.','Review immune status and the original regimen.'],[['Antibody','Can persist'],['Relapse','Needs clinical and appropriate direct assessment'],['Test of cure','Do not use rK39 alone']],[VL])
q('Which kala-azar treatment distinction is important in the Indian setting?', 'Liposomal amphotericin is a first-line approach for suitable uncomplicated disease, while HIV coinfection requires a specialized region-specific regimen',[
 ('The same single-dose strategy applies automatically to every HIV-coinfected patient','Coinfection changes treatment and relapse risk.'),('Fluconazole is the standard universal first-line drug','It is not.'),('HIV status has no bearing on relapse prevention or follow-up','It materially affects management.')],
 'Region and immune status change antileishmanial treatment', '**WHO India describes liposomal amphotericin-based first-line care.**',['HIV-associated VL can require combination treatment with miltefosine.','The regional regimen and maintenance needs should be followed explicitly.'], '**Avoid a one-regimen-for-all assumption.**',['Assess pregnancy restrictions and organ function.','Monitor relapse risk and coordinate effective ART in coinfection.'],[['Uncomplicated Indian VL','Liposomal amphotericin-based pathway'],['HIV coinfection','Specialized combination/relapse plan'],['Selection','Region and host dependent']],[VI,VH])
q('An asplenic adult has fever, hemolytic anemia and intraerythrocytic parasites with occasional tetrads after tick exposure. Which diagnosis is characteristic?', 'Babesiosis',[
 ('Falciparum malaria as the only possible ring-form diagnosis','Babesia can resemble ring forms; tetrads and the exposure support babesiosis.'),('Visceral leishmaniasis','Its amastigotes are not the typical intraerythrocytic tetrads.'),('Acquired hemophilia','It does not create red-cell parasites.')],
 'Host splenic function changes the severity of a red-cell infection', '**Babesia can cause severe hemolysis in asplenic or immunocompromised people.**',['Smear and PCR support confirmation.','Transfusion transmission is also possible.'], '**Assess severity and parasite burden.**',['Organ failure or high burden may require specialist exchange-transfusion assessment.','Do not select a malaria regimen solely from a ring-like appearance.'],[['Clue','Tetrads/Maltese-cross forms'],['Risk','Asplenia'],['Confirmation','Smear and/or PCR']],[BA],style='clinical_scenario')
q('Which combination is preferred for many non-life-threatening babesiosis cases?', 'Atovaquone plus azithromycin',[
 ('Primaquine alone','It is not an adequate babesiosis treatment.'),('Metronidazole plus paromomycin','That is an amebiasis strategy.'),('Isoniazid plus rifampicin','That does not provide the recommended Babesia regimen.')],
 'Treatment is organism-specific despite a shared red-cell location', '**Atovaquone–azithromycin is the preferred combination for many patients.**',['Clindamycin–quinine is an alternative.','Immunocompromised patients may need extended treatment and monitoring.'], '**Tailor therapy to severity.**',['Assess organ dysfunction and parasite trends.','Severe disease warrants expert evaluation for additional support.'],[['Preferred combination','Atovaquone plus azithromycin'],['Alternative','Clindamycin plus quinine'],['Duration','Host and severity dependent']],[BA])
q('A patient from Latin America has conduction disease and an apical ventricular aneurysm without obstructive coronary disease. Which infection is characteristic?', 'Chronic Trypanosoma cruzi infection',[
 ('Giardiasis','It does not cause this characteristic cardiomyopathy.'),('Schistosoma haematobium infection','It primarily suggests a urinary disease association.'),('Acute amebic colitis','It does not explain the chronic cardiac pattern.')],
 'A chronic parasitic infection can cause electrical and structural heart disease', '**Chagas cardiomyopathy can involve conduction abnormalities, arrhythmia and aneurysm.**',['Thromboembolism and heart failure are important complications.','Digestive involvement can also occur.'], '**Confirm chronic infection with the appropriate serological pathway.**',['Assess cardiac function and rhythm.','Antiparasitic decisions depend on age, stage and clinical circumstances.'],[['Cause','T. cruzi'],['Cardiac','Conduction disease and aneurysm'],['Care','Infection confirmation plus cardiac management']],[CH,CT],style='clinical_scenario')
q('How is chronic Chagas infection usually confirmed?', 'At least two serological tests using different antigen preparations or methods, with discordance resolved appropriately',[
 ('A single negative blood smear as definitive exclusion','Parasitemia is often low in chronic infection.'),('A positive ECG pattern alone','It suggests a phenotype but does not prove the infection.'),('A Widal titer','It is unrelated to the Chagas diagnostic pathway.')],
 'Chronic parasitemia and immune evidence differ from acute disease', '**No single serological test is sufficiently definitive in every setting.**',['Use appropriately independent assays.','PCR has roles in acute disease and reactivation but a negative result does not exclude all chronic infection.'], '**Interpret results with epidemiological exposure.**',['Offer specialist stage-appropriate treatment assessment.','Evaluate congenital or family exposure questions where relevant.'],[['Chronic diagnosis','Two appropriate serological assays'],['Smear','Often insensitive chronically'],['Clinical context','Exposure and organ assessment']],[CH])

if __name__=='__main__':print('Parasitic protozoal block: '+str(len(rows))+' questions drafted')
